const providerDescription = (provider: PublicProviderMetadata) => `${provider.displayName} provider managed by the canonical provider registry.`;
const providerOptions = (kind: ProviderKind): Readonly<Record<string, ProviderOption>> => Object.freeze(Object.fromEntries(PUBLIC_PROVIDER_METADATA.filter((provider) => provider.kind === kind && provider.enabled).map((provider) => {
  const credentials = PUBLIC_PROVIDER_CREDENTIAL_DESCRIPTORS[provider.id] || [];
  const primarySecret = credentials.find((credential) => credential.kind === "secret" || credential.kind === "oauth");
  const primaryUrl = credentials.find((credential) => credential.kind === "url");
  return [provider.id, { value: provider.id, label: provider.displayName, description: providerDescription(provider), icon: provider.icon, ...(DEFAULT_PROVIDER_ENDPOINTS[provider.id] ? { url: DEFAULT_PROVIDER_ENDPOINTS[provider.id] } : {}), ...(kind === "image" ? { requiresApiKey: Boolean(primarySecret), apiKeyField: primarySecret?.settingKey, apiKeyFieldLabel: primarySecret?.label, urlField: primaryUrl?.settingKey, urlLabel: primaryUrl?.label } : {}), ...(kind === "web-search" ? (primaryUrl ? { urlField: primaryUrl.settingKey, urlLabel: primaryUrl.label } : primarySecret ? { apiKeyField: primarySecret.settingKey, apiKeyLabel: primarySecret.label } : {}) : {}) }];
})));
